UPDATE /* uptMemberLeave */ TB_CLMEMX MEMBER
  JOIN TM_CLUBXM CLUB
    ON CLUB.CLUB_NUMB = MEMBER.CLUB_NUMB
   AND (CLUB.OWNR_NUMB IS NULL OR CLUB.OWNR_NUMB != #{userNumb})
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = MEMBER.USER_NUMB
   AND USERX.USER_STAT = #{userActive}
   SET MEMBER.MEMB_STAT = #{memberExited}
     , MEMBER.EXIT_DATE = CURRENT_TIMESTAMP(6)
     , MEMBER.BLOC_YSNO = #{commNo}
     , MEMBER.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{userNumb}
   AND MEMBER.MEMB_ROLE = #{memberRole}
   AND MEMBER.MEMB_STAT = #{memberActive}

