DELETE /* delMemberBookVotes */
  FROM TB_CLBVOT
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}

DELETE /* delMemberBookRecs */
  FROM TB_CLBREC
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}

DELETE /* delMemberElectionVotes */
  FROM TB_CLVOTR
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}

DELETE /* delMemberRoundLinks */
  FROM TB_CLPART
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}

DELETE /* delMemberResultHistory */
  FROM TH_CLRSLT
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}

